//! End-to-end tests of the clust binary.
//!
//! Expected centroids and hits are those of `vsearch --cluster_smallmem
//! --usersort --sizein --sizeout --centroids --uc --notrunclabels --qmask
//! soft --minseqlength 0 --fasta_width 0` on the same input. Each sequence,
//! in input order, is searched against the centroids so far as by
//! `--usearch_global`. It joins the cluster of its best accepted hit or
//! becomes a centroid. Sorted first by `sortby`, the input gives
//! `--cluster_fast` and `--cluster_size`. The options are vsearch's, in
//! words: `--size-order` is `--sizeorder`, `--word-len` `--wordlength`,
//! `--max-diffs` `--maxdiffs`, and so on.

use std::path::PathBuf;
use std::process::{Command, Output, Stdio};

